import React from 'react';
import { Bar, Pie } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, ArcElement, Tooltip, Legend } from 'chart.js';

// Chart.js මොඩියුල register කිරීම
ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, Tooltip, Legend);

export default function ChartComponent({ type }) {
  // දත්ත (මෙම දත්ත ඔයාගේ තිබුණු ඒවාමයි)
  const teacherData = { /* ... ඔයාගේ බාර් චාට් දත්ත ... */ };
  const classData = { 
    labels: ['Math', 'Science', 'English', 'History', 'IT'],
    datasets: [{
      data: [30, 25, 15, 20, 10], // නිදසුනක් ලෙස
      backgroundColor: ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#00BFFF'],
    }]
  };

  const pieOptions = {
    responsive: true,
    maintainAspectRatio: false, // බොක්ස් එකේ ඉඩ සම්පූර්ණයෙන්ම පිරවීමට
    plugins: {
      legend: {
        position: 'right', // සබ්ජෙක්ට් ලිස්ට් එක දකුණු පසට
      },
      tooltip: {
        callbacks: {
          label: function(context) {
            let label = context.label || '';
            let value = context.parsed;
            let total = context.dataset.data.reduce((a, b) => a + b, 0);
            let percentage = ((value / total) * 100).toFixed(0) + '%';
            return `${label}: ${percentage}`;
          }
        }
      }
    }
  };

  return (
    <>
      {type === 'bar' ? (
        <Bar data={teacherData} />
      ) : (
        <Pie data={classData} options={pieOptions} />
      )}
    </>
  );
}
